SELECT mb.id, mb.room_id, mr.room_name, mb.user_id, su.username, mb.start_time, mb.end_time, mb.status, mb.reject_reason, mb.title, mb.reason, mb.create_time FROM meeting_booking mb LEFT JOIN meeting_room mr ON mb.room_id = mr.id AND mr.deleted = 0 LEFT JOIN sys_user su ON mb.user_id = su.id
mb.deleted = 0
AND mb.room_id = #{roomId}
AND mb.status = #{resStatus}
ORDER BY mb.create_time DESC

SELECT mb.id, mb.room_id, mr.room_name, mb.user_id, su.username, mb.start_time, mb.end_time, mb.status, mb.reject_reason, mb.title, mb.reason, mb.create_time FROM meeting_booking mb LEFT JOIN meeting_room mr ON mb.room_id = mr.id AND mr.deleted = 0 LEFT JOIN sys_user su ON mb.user_id = su.id
mb.deleted = 0 AND mb.user_id = #{userId}
AND mb.room_id = #{roomId}
AND mb.status = #{resStatus}
ORDER BY mb.create_time DESC

SELECT mb.id, mb.room_id, mr.room_name, mb.user_id, su.username, mb.start_time, mb.end_time, mb.status, mb.reject_reason, mb.title, mb.reason, mb.create_time FROM meeting_booking mb LEFT JOIN meeting_room mr ON mb.room_id = mr.id AND mr.deleted = 0 LEFT JOIN sys_user su ON mb.user_id = su.id
mb.deleted = 0
AND mb.room_id = #{dto.roomId}
AND mb.status = #{dto.resStatus}
AND mb.start_time >= #{dto.startTime}
AND mb.end_time <= #{dto.endTime}
ORDER BY mb.create_time DESC

